import React, { useState, useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { ordersApi, couponsApi } from '../services/api';

const Checkout = () => {
    const location = useLocation();
    const navigate = useNavigate();

    const { subtotal, cartItems } = location.state || { subtotal: 0, cartItems: [] };

    const addressInputRef = useRef(null);
    const autocompleteRef = useRef(null);

    const [addressDetail, setAddressDetail] = useState('');
    const [shippingFullAddress, setShippingFullAddress] = useState('');
    const [shippingLatLng, setShippingLatLng] = useState(null);

    const [couponCode, setCouponCode] = useState('');
    const [discount, setDiscount] = useState(0);

    const [shippingFee, setShippingFee] = useState(0);
    const [distanceKm, setDistanceKm] = useState(0);
    const [isCalculatingShip, setIsCalculatingShip] = useState(false);
    const [canDeliver, setCanDeliver] = useState(false);
    const [shippingMessage, setShippingMessage] = useState('');

    const MAX_DELIVERY_DISTANCE_KM = 300;

    const [formData, setFormData] = useState({
        name: '',
        phone: '',
        email: '',
        notes: ''
    });

    const [paymentMethod, setPaymentMethod] = useState('Cash On Delivery');

    const totalAmount = Math.max(0, subtotal - discount) + shippingFee;

    const handleInputChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handleGoBack = () => {
        navigate('/cart');
    };

    const resetShipping = (message = '') => {
        setShippingFee(0);
        setDistanceKm(0);
        setCanDeliver(false);
        setShippingLatLng(null);
        setShippingMessage(message);
    };

    // Khởi tạo Google Maps Autocomplete
    useEffect(() => {
        let intervalId = null;

        const initGoogleAutocomplete = () => {
            if (!window.google || !window.google.maps || !window.google.maps.places) {
                return false;
            }

            if (!addressInputRef.current || autocompleteRef.current) {
                return true;
            }

            autocompleteRef.current = new window.google.maps.places.Autocomplete(addressInputRef.current, {
                componentRestrictions: { country: 'vn' },
                fields: ['formatted_address', 'geometry', 'name']
            });

            autocompleteRef.current.addListener('place_changed', () => {
                const place = autocompleteRef.current.getPlace();

                if (!place.geometry || !place.geometry.location) {
                    setShippingLatLng(null);
                    setCanDeliver(false);
                    setShippingFee(0);
                    setDistanceKm(0);
                    setShippingMessage('Không lấy được tọa độ địa chỉ. Vui lòng chọn địa chỉ từ gợi ý Google Maps.');
                    return;
                }

                const lat = place.geometry.location.lat();
                const lng = place.geometry.location.lng();
                const fullAddress = place.formatted_address || place.name || '';

                setAddressDetail(fullAddress);
                setShippingFullAddress(fullAddress);
                setShippingLatLng({ lat, lng });

                setShippingFee(0);
                setDistanceKm(0);
                setCanDeliver(false);
                setShippingMessage('');
            });

            return true;
        };

        if (!initGoogleAutocomplete()) {
            intervalId = setInterval(() => {
                const loaded = initGoogleAutocomplete();

                if (loaded && intervalId) {
                    clearInterval(intervalId);
                }
            }, 500);
        }

        return () => {
            if (intervalId) {
                clearInterval(intervalId);
            }
        };
    }, []);

    // Tính phí ship bằng Google Directions
    useEffect(() => {
        if (!shippingLatLng) {
            return;
        }

        const calculateShippingByGoogleMap = () => {
            if (!window.google || !window.google.maps) {
                setShippingFee(0);
                setCanDeliver(false);
                setShippingMessage('Google Maps chưa tải xong. Vui lòng thử lại sau.');
                return;
            }

            setIsCalculatingShip(true);
            setShippingFee(0);
            setCanDeliver(false);
            setShippingMessage('');

            // Tọa độ cửa hàng: 236 Hoàng Quốc Việt, Hà Nội
            const shopLocation = {
                lat: 21.046386,
                lng: 105.795495
            };

            const directionsService = new window.google.maps.DirectionsService();

            directionsService.route(
                {
                    origin: shopLocation,
                    destination: shippingLatLng,
                    travelMode: window.google.maps.TravelMode.DRIVING
                },
                (result, status) => {
                    setIsCalculatingShip(false);

                    if (status !== 'OK' || !result.routes || result.routes.length === 0) {
                        setShippingFee(0);
                        setCanDeliver(false);
                        setShippingMessage('Không tìm được tuyến đường giao hàng. Vui lòng chọn địa chỉ khác.');
                        return;
                    }

                    const legs = result.routes[0].legs || [];

                    const totalMeters = legs.reduce((sum, leg) => {
                        return sum + (leg.distance?.value || 0);
                    }, 0);

                    const distance = totalMeters / 1000;
                    setDistanceKm(distance);

                    if (distance > MAX_DELIVERY_DISTANCE_KM) {
                        setShippingFee(0);
                        setCanDeliver(false);
                        setShippingMessage(
                            `Khoảng cách ${distance.toFixed(1)} km vượt quá phạm vi giao hàng 300km. Shop chỉ giao gần để trái cây luôn tươi ngon.`
                        );
                        return;
                    }

                    let calculatedFee = 15000 + Math.round(distance) * 5000;

                    if (distance < 2) {
                        calculatedFee = 15000;
                    }

                    if (calculatedFee > 150000) {
                        calculatedFee = 150000;
                    }

                    setShippingFee(calculatedFee);
                    setCanDeliver(true);
                    setShippingMessage(`Khoảng cách đường đi: ${distance.toFixed(1)} km - Đủ điều kiện giao hàng.`);
                }
            );
        };

        calculateShippingByGoogleMap();
    }, [shippingLatLng]);

    const handleApplyCoupon = async () => {
        if (!couponCode) {
            alert('Ní vui lòng nhập mã giảm giá trước nhé!');
            return;
        }

        try {
            const response = await couponsApi.check(couponCode);
            const data = response.data;
            const phanTramGiam = data.discountPercent / 100;

            setDiscount(subtotal * phanTramGiam);
            alert(`Áp dụng thành công! Giảm ${data.discountPercent}% cho đơn hàng. 🌟`);
        } catch (error) {
            setDiscount(0);
            alert(error.response?.data || 'Mã giảm giá không hợp lệ hoặc đã hết hạn!');
        }
    };

    const handlePlaceOrder = async (e) => {
        e.preventDefault();

        if (!addressDetail || !shippingLatLng) {
            alert('Ní vui lòng nhập địa chỉ và chọn đúng gợi ý từ Google Maps nhé!');
            return;
        }

        if (!canDeliver) {
            alert('Địa chỉ này nằm ngoài phạm vi giao hàng 300km. Shop chỉ giao gần để trái cây luôn tươi ngon!');
            return;
        }

        const userData = JSON.parse(localStorage.getItem('user') || '{}');
        const currentUserId = userData.userId || userData.id;

        if (!currentUserId) {
            alert('Vui lòng đăng nhập tài khoản để đặt hàng!');
            navigate('/login');
            return;
        }

        if (!cartItems || cartItems.length === 0) {
            alert('Giỏ hàng đang trống, không thể đặt hàng!');
            navigate('/cart');
            return;
        }

        const fullShippingAddress = `${shippingFullAddress || addressDetail} (KM: ${distanceKm.toFixed(1)})`;

        const orderData = {
            userId: currentUserId,
            shippingAddress: fullShippingAddress,
            phone: formData.phone,
            orderNotes: formData.notes,
            paymentMethod: paymentMethod,
            subTotal: subtotal,
            shippingFee: shippingFee,
            discountAmount: discount,
            totalAmount: totalAmount,
            couponCode: couponCode,
            details: cartItems.map(item => ({
                productId: item.productId || item.id,
                quantity: item.quantity,
                unitPrice: item.discountPrice || item.price
            }))
        };

        try {
            await ordersApi.checkout(orderData);
            alert('🎉 Đặt hàng thành công! Đơn hàng của ní đang chờ hệ thống xử lý.');
            navigate('/my-orders');
        } catch (error) {
            alert(`Đặt hàng thất bại: ${error.response?.data || 'Lỗi máy chủ C#!'}`);
        }
    };

    return (
        <>
            <div className="container-fluid page-header py-5">
                <h1 className="text-center text-white display-6">Thanh Toán Đơn Hàng</h1>
            </div>

            <div className="container-fluid py-5">
                <div className="container py-5">
                    <div className="mb-4">
                        <button
                            type="button"
                            className="btn btn-outline-secondary rounded-pill px-4 py-2 fw-bold"
                            onClick={handleGoBack}
                        >
                            <i className="fa fa-arrow-left me-2"></i>
                            Quay lại giỏ hàng
                        </button>
                    </div>

                    <form onSubmit={handlePlaceOrder}>
                        <div className="row g-5">
                            <div className="col-md-12 col-lg-6 col-xl-7">
                                <h2 className="mb-4">Thông tin giao hàng</h2>

                                <div className="row">
                                    <div className="col-md-12 col-lg-6">
                                        <div className="form-item w-100 mb-3">
                                            <label className="form-label mb-2">
                                                Họ và Tên người nhận<sup>*</sup>
                                            </label>
                                            <input
                                                type="text"
                                                name="name"
                                                className="form-control"
                                                value={formData.name}
                                                onChange={handleInputChange}
                                                required
                                            />
                                        </div>
                                    </div>

                                    <div className="col-md-12 col-lg-6">
                                        <div className="form-item w-100 mb-3">
                                            <label className="form-label mb-2">
                                                Số điện thoại<sup>*</sup>
                                            </label>
                                            <input
                                                type="text"
                                                name="phone"
                                                className="form-control"
                                                value={formData.phone}
                                                onChange={handleInputChange}
                                                required
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="form-item mb-4">
                                    <label className="form-label mb-2">
                                        Địa chỉ giao hàng <sup>*</sup>
                                    </label>

                                    <input
                                        ref={addressInputRef}
                                        type="text"
                                        className="form-control border-warning"
                                        placeholder="Nhập địa chỉ và chọn gợi ý từ Google Maps..."
                                        value={addressDetail}
                                        onChange={(e) => {
                                            setAddressDetail(e.target.value);
                                            setShippingFullAddress(e.target.value);
                                            resetShipping('Vui lòng chọn địa chỉ từ gợi ý Google Maps để tính phí ship.');
                                        }}
                                        required
                                    />

                                    <small className="text-muted d-block mt-2">
                                        Nhập địa chỉ rồi bấm chọn gợi ý hiện ra từ Google Maps để hệ thống xác định vị trí chính xác.
                                    </small>
                                </div>

                                <div className="form-item mb-4">
                                    <textarea
                                        name="notes"
                                        className="form-control"
                                        rows="3"
                                        placeholder="Ghi chú cho Shipper (Tùy chọn)..."
                                        value={formData.notes}
                                        onChange={handleInputChange}
                                    ></textarea>
                                </div>

                                <h2 className="mb-4 mt-5">Phương thức thanh toán</h2>

                                <div className="p-4 bg-light rounded border">
                                    <div className="form-check mb-3">
                                        <input
                                            className="form-check-input"
                                            type="radio"
                                            name="payment"
                                            id="cod"
                                            value="Cash On Delivery"
                                            checked={paymentMethod === 'Cash On Delivery'}
                                            onChange={(e) => setPaymentMethod(e.target.value)}
                                        />
                                        <label className="form-check-label fw-bold" htmlFor="cod">
                                            Thanh toán khi nhận hàng (COD)
                                        </label>
                                    </div>

                                    <div className="form-check mb-3">
                                        <input
                                            className="form-check-input"
                                            type="radio"
                                            name="payment"
                                            id="momo"
                                            value="MoMo"
                                            checked={paymentMethod === 'MoMo'}
                                            onChange={(e) => setPaymentMethod(e.target.value)}
                                        />
                                        <label className="form-check-label fw-bold" htmlFor="momo">
                                            Thanh toán qua Ví điện tử MoMo
                                        </label>
                                    </div>

                                    <div className="form-check">
                                        <input
                                            className="form-check-input"
                                            type="radio"
                                            name="payment"
                                            id="bank"
                                            value="Bank Transfer"
                                            checked={paymentMethod === 'Bank Transfer'}
                                            onChange={(e) => setPaymentMethod(e.target.value)}
                                        />
                                        <label className="form-check-label fw-bold" htmlFor="bank">
                                            Chuyển khoản Ngân hàng (Quét mã QR)
                                        </label>
                                    </div>

                                    {paymentMethod === 'Bank Transfer' && (
                                        <div className="mt-4 text-center bg-white p-3 rounded border border-info">
                                            <h5 className="text-info mb-3">Quét mã QR để thanh toán tự động</h5>
                                            <p className="small text-muted mb-2">
                                                Ngân hàng MB Bank - Chủ TK: TRAN VAN TINH
                                            </p>
                                            <img
                                                src={`https://img.vietqr.io/image/mbbank-0999888777-compact2.png?amount=${Math.round(totalAmount)}&addInfo=ThanhToanFruitables`}
                                                alt="QR Code Ngân Hàng"
                                                style={{ width: '200px' }}
                                            />
                                            <p className="mt-2 fw-bold text-danger">
                                                Tổng thanh toán: {totalAmount.toLocaleString('vi-VN')} VNĐ
                                            </p>
                                        </div>
                                    )}

                                    {paymentMethod === 'MoMo' && (
                                        <div
                                            className="mt-4 text-center bg-white p-3 rounded border"
                                            style={{ borderColor: '#A50064' }}
                                        >
                                            <h5 className="mb-3" style={{ color: '#A50064' }}>
                                                Mở ứng dụng MoMo để quét mã
                                            </h5>
                                            <img
                                                src="https://upload.wikimedia.org/wikipedia/commons/d/d0/QR_code_for_mobile_English_Wikipedia.svg"
                                                alt="MoMo QR"
                                                style={{
                                                    width: '150px',
                                                    border: '5px solid #A50064',
                                                    borderRadius: '10px'
                                                }}
                                            />
                                            <p className="mt-2 fw-bold text-danger">
                                                Tổng thanh toán: {totalAmount.toLocaleString('vi-VN')} VNĐ
                                            </p>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="col-md-12 col-lg-6 col-xl-5">
                                <div className="table-responsive bg-light rounded p-5 border">
                                    <h2 className="display-6 mb-4" style={{ fontSize: '26px' }}>
                                        Hóa đơn đơn hàng
                                    </h2>

                                    <div className="input-group mb-4">
                                        <input
                                            type="text"
                                            className="form-control py-3"
                                            placeholder="Nhập mã giảm giá..."
                                            value={couponCode}
                                            onChange={(e) => setCouponCode(e.target.value)}
                                        />

                                        <button
                                            className="btn btn-warning fw-bold text-dark px-4"
                                            type="button"
                                            onClick={handleApplyCoupon}
                                        >
                                            ÁP DỤNG
                                        </button>
                                    </div>

                                    <table className="table align-middle mt-2">
                                        <thead>
                                            <tr>
                                                <th scope="col">Hình</th>
                                                <th scope="col">Sản phẩm</th>
                                                <th scope="col">Thành tiền</th>
                                            </tr>
                                        </thead>

                                        <tbody>
                                            {cartItems && cartItems.length > 0 ? (
                                                cartItems.map((item, index) => {
                                                    const finalPrice = item.discountPrice || item.price;

                                                    return (
                                                        <tr key={index}>
                                                            <td>
                                                                <img
                                                                    src={item.imageUrl || '/img/avatar.jpg'}
                                                                    style={{
                                                                        width: '45px',
                                                                        height: '45px',
                                                                        objectFit: 'cover',
                                                                        borderRadius: '50%'
                                                                    }}
                                                                    alt={item.name || 'Sản phẩm'}
                                                                />
                                                            </td>

                                                            <td>
                                                                {item.name}{' '}
                                                                <span className="text-muted fw-bold">
                                                                    x{item.quantity}
                                                                </span>
                                                            </td>

                                                            <td className="fw-bold">
                                                                {(finalPrice * item.quantity).toLocaleString('vi-VN')} đ
                                                            </td>
                                                        </tr>
                                                    );
                                                })
                                            ) : (
                                                <tr>
                                                    <td colSpan="3" className="text-center text-danger fw-bold">
                                                        Không có sản phẩm nào trong đơn hàng.
                                                    </td>
                                                </tr>
                                            )}

                                            <tr className="border-top">
                                                <td colSpan="2">
                                                    <strong>Tổng tiền hàng:</strong>
                                                </td>
                                                <td className="fw-bold">
                                                    {subtotal.toLocaleString('vi-VN')} đ
                                                </td>
                                            </tr>

                                            {discount > 0 && (
                                                <tr className="text-success">
                                                    <td colSpan="2">
                                                        <strong>Khấu trừ mã giảm giá:</strong>
                                                    </td>
                                                    <td className="fw-bold">
                                                        -{discount.toLocaleString('vi-VN')} đ
                                                    </td>
                                                </tr>
                                            )}

                                            <tr>
                                                <td colSpan="2">
                                                    <strong>Phí vận chuyển:</strong>
                                                    <br />

                                                    {isCalculatingShip ? (
                                                        <small className="text-warning fw-bold">
                                                            <i className="fa fa-spinner fa-spin me-1"></i>
                                                            Đang tính phí...
                                                        </small>
                                                    ) : !shippingLatLng ? (
                                                        <small className="text-danger fw-bold">
                                                            *Chọn địa chỉ từ Google Maps để tính phí
                                                        </small>
                                                    ) : !canDeliver ? (
                                                        <small className="text-danger fw-bold">
                                                            {shippingMessage}
                                                        </small>
                                                    ) : (
                                                        <small className="text-success fw-bold">
                                                            {shippingMessage}
                                                        </small>
                                                    )}
                                                </td>

                                                <td>
                                                    <strong className={shippingFee === 0 ? 'text-danger' : 'text-dark'}>
                                                        {shippingFee === 0 ? '---' : `${shippingFee.toLocaleString('vi-VN')} đ`}
                                                    </strong>
                                                </td>
                                            </tr>

                                            <tr className="border-top border-dark border-2 bg-white">
                                                <td colSpan="2">
                                                    <h5 className="mb-0 text-primary fw-bold">
                                                        TỔNG THANH TOÁN:
                                                    </h5>
                                                </td>

                                                <td>
                                                    <h5 className="mb-0 text-danger fw-bold">
                                                        {totalAmount.toLocaleString('vi-VN')} đ
                                                    </h5>
                                                </td>
                                            </tr>
                                        </tbody>
                                    </table>

                                    <button
                                        type="submit"
                                        className="btn border-secondary bg-primary text-white py-3 px-4 text-uppercase w-100 fw-bold mt-4"
                                        disabled={!canDeliver || shippingFee === 0 || isCalculatingShip}
                                    >
                                        {isCalculatingShip
                                            ? 'ĐANG TÍNH TIỀN...'
                                            : !canDeliver && shippingLatLng
                                                ? 'KHÔNG HỖ TRỢ GIAO HÀNG'
                                                : 'XÁC NHẬN ĐẶT HÀNG NGAY'}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </form>
                </div>
            </div>
        </>
    );
};

export default Checkout;
